#!/usr/bin/env python3
"""unidaw MCP server — kapselt die HTTP-Befehls-API des Agent-DAW (unidaw).

MCP über stdio (newline-delimited JSON-RPC 2.0), ohne Abhängigkeiten.
Tools: unidaw_start (startet den Daemon, idempotent), unidaw_command (ein Befehl).
"""
import json
import os
import subprocess
import sys
import time
import urllib.error
import urllib.request

VERSION = "0.1.0"  # = project(unidaw VERSION) in dawd/CMakeLists.txt, prueft die Suite
UNIDAW_URL = "http://127.0.0.1:7400"
# Was unidaw_start startet: UNIDAW_BIN (unidaw-Binary oder das AppImage), sonst der
# Build im Entwickler-Checkout. Plugin- und MCPB-Nutzer haben nur das
# AppImage: ohne UNIDAW_BIN starten sie unidaw selbst (README).
UNIDAW_BIN = os.environ.get("UNIDAW_BIN") or os.path.expanduser("~/dev/agent-daw/dawd/build/unidaw_artefacts/Release/unidaw")
UNIDAW_RUN_DIR = os.path.expanduser("~/.local/state/unidaw" if os.environ.get("UNIDAW_BIN") else "~/dev/agent-daw/dawd/run")
# Config-Ordner der gestarteten unidaw (ihr Standard): dort liegt der Token der
# Sitzung, api-token-<port>
UNIDAW_CONFIG = os.path.expanduser("~/.config/unidaw")
# Gibt es nur den Ordner aus der Zeit vor dem Namen unidaw, nimmt unidaw ihn
# weiter (dawd/source/main.cpp) — der Token liegt dann dort
if not os.path.isdir(UNIDAW_CONFIG) and os.path.isdir(os.path.expanduser("~/.config/dawd")):
    UNIDAW_CONFIG = os.path.expanduser("~/.config/dawd")

